1	export type BookSetup = {
2	  id: string;
3	  label: string;
4	  costUsd: number | null;
5	  sessions: number;
6	  survivingChanges: number;
7	  unattendedShare: number;
8	};
9	
10	export type BookInput = {
11	  periodDays: number;
12	  setups: BookSetup[];
13	  promoted: string | null;
14	  assumptions: { engineerMonthlyLoadedUsd: number; scaleSessionsPerWeek: number };
15	};
16	
17	export type BookOutput = {
18	  department: {
19	    setup: string;
20	    label: string;
21	    monthlySpendUsd: number | null;
22	    survivingChangesPerMonth: number;
23	    costPerSurvivingChangeUsd: number | null;
24	    unattendedPct: number;
25	  }[];
26	  scenario: {
27	    hireMonthlyUsd: number;
28	    scaleMonthlyUsd: number | null;
29	    scaleSurvivingChangesPerMonth: number | null;
30	  };
31	  assumptions: Record<string, number>;
32	};
33	
34	const cents = (n: number): number => Math.round(n * 100) / 100;
35	const tenth = (n: number): number => Math.round(n * 10) / 10;
36	
37	export function buildBook(input: BookInput): BookOutput {
38	  const { periodDays, setups, promoted, assumptions } = input;
39	  const toMonth = (v: number): number => (v * 30) / periodDays;
40	
41	  const department = setups.map((s) => {
42	    const spend = s.costUsd === null ? null : toMonth(s.costUsd);
43	    const surviving = toMonth(s.survivingChanges);
44	    const costPer =
45	      spend === null || s.survivingChanges === 0 ? null : cents(spend / surviving);
46	    return {
47	      setup: s.id,
48	      label: s.label,
49	      monthlySpendUsd: spend === null ? null : cents(spend),
50	      survivingChangesPerMonth: surviving,
51	      costPerSurvivingChangeUsd: costPer,
52	      unattendedPct: tenth(s.unattendedShare * 100),
53	    };
54	  });
55	
56	  const p = promoted === null ? undefined : setups.find((s) => s.id === promoted);
57	  const sessionsPerMonth = assumptions.scaleSessionsPerWeek * (30 / 7);
58	  const canScale = p !== undefined && p.sessions > 0;
59	
60	  return {
61	    department,
62	    scenario: {
63	      hireMonthlyUsd: cents(assumptions.engineerMonthlyLoadedUsd),
64	      scaleMonthlyUsd:
65	        canScale && p.costUsd !== null
66	          ? cents((p.costUsd / p.sessions) * sessionsPerMonth)
67	          : null,
68	      scaleSurvivingChangesPerMonth: canScale
69	        ? (p.survivingChanges / p.sessions) * sessionsPerMonth
70	        : null,
71	    },
72	    assumptions: { ...assumptions },
73	  };
74	}
