1	// `roster review <repo> --observational`: fetch → parse → identify → score, then reports/<slug>/.
2	// Every stage is a TOOL span inside one WORKFLOW review span (DESIGN.md §"Observability (neatlogs)"). The
3	// review ends with one line of wall time per stage.
4	import { join, resolve } from "node:path";
5	import type { Command } from "../cli.ts";
6	import { priceSession } from "../price/index.ts";
7	import { flushObs, initObs, setSession, withSpan } from "../obs/index.ts";
8	import { ATTR, summaryAttr } from "../obs/attributes.ts";
9	import { fetchCheckpoints } from "../ingest/fetch.ts";
10	import { type ParsedSession, parseCheckpoints } from "../ingest/parse.ts";
11	import { type Identity, identify, inferenceAccuracy } from "../identity/index.ts";
12	import { survival, survivalMany } from "../score/survival.ts";
13	import { isReverted, reverted } from "../score/revert.ts";
14	import { BUDGET_MESSAGE, gitFailure, gitPool, type GitResult, type GitRunner, rework, reworkShares, trackMany } from "../score/rework.ts";
15	import { reviewDifficulty } from "../difficulty/index.ts";
16	import { buildSetupRows, buildTags, repoSlug, type ReviewReport, slugDir, writeReview } from "../review/export.ts";
17	import { NO_SUSPECT_LABEL, type SetupOutcome, SUSPECT_LABEL, suspect } from "../review/suspect.ts";
18	import type { Outcome, Review, ReviewLabel, Session } from "../types.ts";
19	
20	export const DEFAULT_CACHE = ".roster/cache";
21	/** Mature = at least this many first-parent commits after the session's commit, and this many seconds older than HEAD. */
22	export const MIN_DEPTH = 5;
23	export const MIN_AGE_S = 6 * 3600;
24	
25	const STAGES = ["fetch", "parse", "identify", "score"] as const;
26	type Stage = (typeof STAGES)[number];
27	
28	const USAGE = `usage: roster review <repo> --observational [--out <dir>] [--cache <dir>]
29	
30	  <repo>            a git URL or a local path to a repo that has Entire checkpoints
31	  --observational   score sessions that already exist (evidence level A). Required for now.
32	  --out <dir>       where to write review.json, review.md, sessions.json and outcomes.json
33	                    (default reports/<slug>)
34	  --cache <dir>     fetch cache (default ${DEFAULT_CACHE})`;
35	
36	export interface ReviewArgs {
37	  repo: string;
38	  out: string | undefined;
39	  cache: string;
40	}
41	
42	/** Thrown for bad arguments. The CLI prints the message and exits 2. */
43	export class UsageError extends Error {}
44	
45	/** Parses the arguments after `review`. Throws UsageError on anything it does not accept. */
46	export function parseReviewArgs(args: string[]): ReviewArgs {
47	  let repo: string | undefined;
48	  let observational = false;
49	  let out: string | undefined;
50	  let cache = DEFAULT_CACHE;
51	  for (let i = 0; i < args.length; i++) {
52	    const a = args[i]!;
53	    const eq = a.indexOf("=");
54	    const name = eq === -1 ? a : a.slice(0, eq);
55	    // A flag takes its value inline (--out=dir) or as the next argument (--out dir).
56	    const takeValue = (): string => {
57	      if (eq !== -1) return a.slice(eq + 1);
58	      const v = args[++i];
59	      if (v === undefined || v.startsWith("--")) throw new UsageError(`${name} needs a value`);
60	      return v;
61	    };
62	    if (name === "--observational" && eq === -1) observational = true;
63	    else if (name === "--out") out = takeValue();
64	    else if (name === "--cache") cache = takeValue();
65	    else if (a.startsWith("-")) throw new UsageError(`unknown flag ${a}`);
66	    else if (repo === undefined) repo = a;
67	    else throw new UsageError(`unexpected argument ${a}`);
68	  }
69	  if (repo === undefined) throw new UsageError("missing <repo>");
70	  if (!observational) {
71	    throw new UsageError("only --observational is implemented; the controlled replay path is not built yet");
72	  }
73	  return { repo, out, cache };
74	}
75	
76	const NO_DATA =
77	  "no Entire data found. Run `entire enable` in the source repo, push its entire/checkpoints/v1 branch, and try again.";
78	
79	function git(repo: string, args: string[]): string {
80	  const p = Bun.spawnSync(["git", "-c", "core.quotepath=off", ...args], { cwd: repo, stdout: "pipe", stderr: "pipe" });
81	  if (p.exitCode !== 0) throw new Error(`git ${args[0]} failed: ${p.stderr.toString().trim()}`);
82	  return p.stdout.toString();
83	}
84	
85	/** Wall time the whole scoring pass may take before the remaining sessions are marked not scored. */
86	export const SCORE_BUDGET_MS = 120_000;
87	const PROGRESS_EVERY = 10;
88	
89	export interface ScoreOptions {
90	  budgetMs?: number;
91	  /** Called with a line like `score: 10/50 sessions, 12.3 s` at every 10th session. */
92	  onProgress?: (line: string) => void;
93	}
94	
95	interface ScoreContext {
96	  repo: string;
97	  head: string;
98	  headTime: number;
99	}
100	
101	/** One user prompt means nobody steered the session. Needs no commit age; null when the count is unknown. */
102	const isUnattended = (s: ParsedSession): boolean | null => (Number.isFinite(s.n_user_prompts) ? s.n_user_prompts === 1 : null);
103	
104	const tooYoung = (session_id: string, unattended: boolean | null = null): Outcome => ({
105	  session_id,
106	  status: "too_young",
107	  survival: null,
108	  reverted: null,
109	  rework_human: null,
110	  rework_agent: null,
111	  unattended,
112	  tests_at_commit: null,
113	  difficulty: null,
114	  tercile: null,
115	});
116	
117	/**
118	 * Scores one session from its commit. Sessions without a trailer-linked commit, and commits that are not yet
119	 * mature, come back too_young with null metrics. Throws when git cannot read the commit.
120	 */
121	export function scoreSession(session: ParsedSession, ctx: ScoreContext): Outcome {
122	  const sha = session.commit_sha;
123	  if (sha === null) return tooYoung(session.id, isUnattended(session));
124	  const depth = Number(git(ctx.repo, ["rev-list", "--count", "--first-parent", `${sha}..${ctx.head}`]).trim());
125	  const age = ctx.headTime - Number(git(ctx.repo, ["show", "-s", "--format=%ct", sha]).trim());
126	  if (depth < MIN_DEPTH || age < MIN_AGE_S) return tooYoung(session.id, isUnattended(session));
127	
128	  const surv = survival(ctx.repo, [sha], ctx.head);
129	  const rw = rework(ctx.repo, sha);
130	  return {
131	    session_id: session.id,
132	    status: "mature",
133	    survival: surv.ratio,
134	    reverted: reverted(ctx.repo, sha),
135	    rework_human: rw.human,
136	    rework_agent: rw.agent,
137	    unattended: isUnattended(session),
138	    tests_at_commit: null,
139	    difficulty: null,
140	    tercile: null,
141	  };
142	}
143	
144	/**
145	 * scoreSession for every session at once, with the same outcomes. Git work goes through `run` (a pool
146	 * of GIT_PARALLEL processes by default): blame runs once per (file, HEAD) and rework and reverts share
147	 * one history pass. Each entry is the session's Outcome, or the Error that stopped it.
148	 */
149	export async function scoreAll(
150	  sessions: ParsedSession[],
151	  ctx: ScoreContext,
152	  inner: GitRunner = gitPool(),
153	  opts: ScoreOptions = {},
154	): Promise<(Outcome | Error)[]> {
155	  const started = performance.now();
156	  const budgetMs = opts.budgetMs ?? SCORE_BUDGET_MS;
157	  // Past the budget every git call is refused, so the sessions still waiting come back not scored.
158	  const run: GitRunner = (repo, args, stdin) => {
159	    const left = budgetMs - (performance.now() - started);
160	    const refused: GitResult = { ok: false, out: "", err: BUDGET_MESSAGE, budget: true };
161	    if (left <= 0) return Promise.resolve(refused);
162	    let timer: ReturnType<typeof setTimeout>;
163	    const expired = new Promise<GitResult>((done) => (timer = setTimeout(() => done(refused), left)));
164	    return Promise.race([inner(repo, args, stdin), expired]).finally(() => clearTimeout(timer));
165	  };
166	  const out = async (args: string[]) => {
167	    const r = await run(ctx.repo, ["-c", "core.quotepath=off", ...args]);
168	    if (!r.ok) throw gitFailure(r, `git ${args[0]}`);
169	    return r.out;
170	  };
171	  const asError = (err: unknown) => (err instanceof Error ? err : new Error(String(err)));
172	
173	  // Maturity: the same two questions scoreSession asks, all sessions in parallel.
174	  const maturity = await Promise.all(
175	    sessions.map(async (s): Promise<string | null | Outcome | Error> => {
176	      const sha = s.commit_sha;
177	      if (sha === null) return tooYoung(s.id, isUnattended(s));
178	      const [depthR, showR] = await Promise.allSettled([
179	        out(["rev-list", "--count", "--first-parent", `${sha}..${ctx.head}`]),
180	        out(["show", "-s", "--format=%H %ct", sha]),
181	      ]);
182	      if (depthR.status === "rejected") return asError(depthR.reason);
183	      if (showR.status === "rejected") return asError(showR.reason);
184	      const [full = "", time = ""] = showR.value.trim().split(" ");
185	      const depth = Number(depthR.value.trim());
186	      if (depth < MIN_DEPTH || ctx.headTime - Number(time) < MIN_AGE_S) return tooYoung(s.id, isUnattended(s));
187	      return full;
188	    }),
189	  );
190	
191	  const mature = [...new Set(maturity.filter((m): m is string => typeof m === "string"))];
192	  let head: string | Error;
193	  try {
194	    head = (await out(["rev-parse", "--verify", `${ctx.head}^{commit}`])).trim();
195	  } catch {
196	    head = new Error(`cannot resolve ${ctx.head} in ${ctx.repo}`);
197	  }
198	  // Progress counts sessions: those already settled (too young, no commit, failed) plus each mature
199	  // commit's sessions as its survival lands. A line goes out at every 10th.
200	  const sessionsOf = new Map<string, number>();
201	  maturity.forEach((m) => typeof m === "string" && sessionsOf.set(m, (sessionsOf.get(m) ?? 0) + 1));
202	  let done = sessions.length - [...sessionsOf.values()].reduce((a, b) => a + b, 0);
203	  let reported = 0;
204	  const advance = (n: number) => {
205	    done += n;
206	    for (; (reported + 1) * PROGRESS_EVERY <= done; reported++) {
207	      const secs = ((performance.now() - started) / 1000).toFixed(1);
208	      opts.onProgress?.(`score: ${(reported + 1) * PROGRESS_EVERY}/${sessions.length} sessions, ${secs} s`);
209	    }
210	  };
211	  advance(0);
212	  const failAll = (err: unknown) => new Map(mature.map((sha) => [sha, asError(err)] as const));
213	  const [surv, tracked] = await Promise.all([
214	    typeof head === "string"
215	      ? survivalMany(ctx.repo, mature.map((sha) => [sha]), head, run, new Map(), (i) => advance(sessionsOf.get(mature[i]!) ?? 0))
216	      : mature.map(() => head as Error),
217	    trackMany(ctx.repo, mature, run).catch(failAll),
218	  ]);
219	  const survOf = new Map(mature.map((sha, i) => [sha, surv[i]!]));
220	
221	  return sessions.map((s, i) => {
222	    const m = maturity[i]!;
223	    if (typeof m !== "string") return m;
224	    const sv = survOf.get(m)!;
225	    if (sv instanceof Error) return sv;
226	    const t = tracked.get(m) ?? new Error(`no history for ${m}`);
227	    if (t instanceof Error) return t;
228	    const rw = reworkShares(t);
229	    return {
230	      session_id: s.id,
231	      status: "mature",
232	      survival: sv.ratio,
233	      reverted: isReverted(t),
234	      rework_human: rw.human,
235	      rework_agent: rw.agent,
236	      unattended: isUnattended(s),
237	      tests_at_commit: null,
238	      difficulty: null,
239	      tercile: null,
240	    };
241	  });
242	}
243	
244	const pct = (x: number) => `${(100 * x).toFixed(1)}%`;
245	
246	/** Wall time per stage, in ms. */
247	type Timings = Map<string, number>;
248	
249	/** Timed stages in print order. */
250	const TIMED = ["fetch", "parse", "identify", "score", "difficulty", "export"] as const;
251	
252	export function formatTimings(times: Timings, totalMs: number): string {
253	  const s = (ms: number) => `${(ms / 1000).toFixed(2)}s`;
254	  const parts = TIMED.map((name) => {
255	    const ms = times.get(name);
256	    return `${name} ${ms === undefined ? "not run" : s(ms)}`;
257	  });
258	  return `time: ${parts.join(" · ")} · total ${s(totalMs)}`;
259	}
260	
261	async function timed<T>(times: Timings, name: string, work: () => Promise<T>): Promise<T> {
262	  const t0 = performance.now();
263	  try {
264	    return await work();
265	  } finally {
266	    times.set(name, performance.now() - t0);
267	  }
268	}
269	
270	async function stage<T>(times: Timings, n: number, name: Stage, repo: string, work: () => Promise<[T, string]>): Promise<T> {
271	  return timed(times, name, () =>
272	    withSpan("TOOL", name, { repo }, async () => {
273	      const [value, detail] = await work();
274	      console.log(`[${n}/${STAGES.length}] ${name}: ${detail}`);
275	      return value;
276	    }),
277	  );
278	}
279	
280	/** Runs the whole review. Resolves to the exit code; writes reports only when every stage succeeds. */
281	export async function runReview(args: ReviewArgs): Promise<number> {
282	  const label = repoSlug(args.repo);
283	  const outDir = resolve(args.out ?? join("reports", slugDir(label)));
284	  const createdAt = new Date().toISOString();
285	  const reviewId = `${slugDir(label)}-${createdAt.replace(/\D/g, "").slice(0, 14)}`;
286	
287	  await initObs({ workflowName: "roster-review" });
288	  setSession(reviewId);
289	  console.log(`roster review ${label} (${reviewId}) → ${outDir}`);
290	  const times: Timings = new Map();
291	  const t0 = performance.now();
292	  try {
293	    // One span per stage, never one per session: session-level detail goes into one roster.summary count line.
294	    return await withSpan("WORKFLOW", "review", { repo: label }, async (root) => {
295	      const fetched = await stage(times, 1, "fetch", label, async () => {
296	        const f = await fetchCheckpoints(args.repo, { cacheDir: resolve(args.cache) });
297	        return [f, `backend=${f.backend} head=${f.headSha.slice(0, 12) || "none"}`];
298	      });
299	      if (fetched.backend === "none") {
300	        console.error(`roster review: ${NO_DATA}`);
301	        return 1;
302	      }
303	      if (fetched.headSha === "") {
304	        console.error("roster review: the repo has checkpoints but no HEAD commit to score them against");
305	        return 1;
306	      }
307	
308	      const sessions = await stage(times, 2, "parse", label, async () => {
309	        const parsed = parseCheckpoints(fetched.repoPath, fetched.backend === "refs" ? "git-refs" : "branch");
310	        return [parsed, `${parsed.length} sessions`];
311	      });
312	
313	      const identities: Identity[] = await stage(times, 3, "identify", label, async () => {
314	        const ids = sessions.map((s) => identify(s, fetched.repoPath));
315	        const setups = new Set(ids.map((i) => i.setupId).filter((x): x is string => x !== null)).size;
316	        const acc = inferenceAccuracy(ids);
317	        return [ids, `${setups} setups, tag accuracy ${acc === null ? "n/a (no tagged sessions)" : pct(acc)}`];
318	      });
319	
320	      const headTime = Number(git(fetched.repoPath, ["show", "-s", "--format=%ct", fetched.headSha]).trim());
321	      const ctx: ScoreContext = { repo: fetched.repoPath, head: fetched.headSha, headTime };
322	      const scored = await stage(times, 4, "score", label, async () => {
323	        const out: Session[] = [];
324	        const outcomes: Outcome[] = [];
325	        const failed: string[] = [];
326	        const scoredAll = await scoreAll(sessions, ctx, undefined, { onProgress: (l) => console.log(l) });
327	        sessions.forEach((s, i) => {
328	          const id = identities[i]!;
329	          const cost = priceSession(s.model, {
330	            input: s.tokens_in,
331	            output: s.tokens_out,
332	            cache_read: s.cache_read,
333	            cache_write: s.cache_write,
334	          }).usd;
335	          out.push({ ...stripParsed(s), setup_id: id.setupId, cost_usd: cost });
336	          const o = scoredAll[i]!;
337	          if (o instanceof Error) {
338	            failed.push(`${s.id}: ${o.message}`);
339	            outcomes.push(tooYoung(s.id, isUnattended(s)));
340	          } else outcomes.push(o);
341	        });
342	        const mature = outcomes.filter((o) => o.status === "mature").length;
343	        return [
344	          { out, outcomes, failed },
345	          `${mature} mature, ${outcomes.length - mature} too young${failed.length ? `, ${failed.length} failed` : ""}`,
346	        ];
347	      });
348	
349	      const difficultyNotes: string[] = [];
350	      const outcomes = await timed(times, "difficulty", () =>
351	        withDifficulty(scored.out, scored.outcomes, fetched.repoPath, difficultyNotes),
352	      );
353	      const call = verdict(scored.out, outcomes);
354	
355	      root.setAttribute(
356	        ATTR.summary,
357	        summaryAttr({
358	          sessions: sessions.length,
359	          mature: scored.outcomes.filter((o) => o.status === "mature").length,
360	          too_young: scored.outcomes.filter((o) => o.status === "too_young").length,
361	          failed: scored.failed.length,
362	          setups: new Set(identities.map((i) => i.setupId).filter((x) => x !== null)).size,
363	          unpriced: scored.out.filter((s) => s.cost_usd === null).length,
364	        }),
365	      );
366	
367	      const notes = [
368	        `${scored.outcomes.filter((o) => o.status === "too_young").length} sessions are too young or have no commit: a session is mature at ≥ ${MIN_DEPTH} first-parent commits and ≥ ${MIN_AGE_S / 3600} h before HEAD`,
369	        ...scored.failed.map((f) => `could not be scored: ${f}`),
370	        `${scored.out.filter((s) => s.cost_usd === null).length} sessions have no price (unknown model, or a price that depends on prompt size)`,
371	        `${scored.out.filter((s) => s.setup_id === null).length} sessions have no setup because their rules hash is unknown`,
372	        `suspect call: ${call.reason}`,
373	        ...difficultyNotes,
374	      ];
375	      const tags = buildTags(scored.out);
376	      const review: Review = {
377	        id: reviewId,
378	        repo: label,
379	        created_at: createdAt,
380	        generated_at: createdAt,
381	        has_entire_data: true,
382	        setups: buildSetupRows(scored.out, scored.outcomes),
383	        ...(tags ? { tags } : {}),
384	        label: call.label,
385	        suspect: call.suspect,
386	        odds_ratio: call.odds_ratio,
387	        ci95: call.ci95,
388	        p_value: call.p_value,
389	        evidence_level: "A",
390	      };
391	      const report: ReviewReport = {
392	        review,
393	        note: call.note,
394	        sessions: scored.out,
395	        outcomes,
396	        notes,
397	      };
398	      const written = await timed(times, "export", async () => writeReview(outDir, report));
399	      console.log(`wrote ${written.join(", ")}`);
400	      console.log(`label ${review.label} · evidence level ${review.evidence_level}`);
401	      return 0;
402	    });
403	  } finally {
404	    if (times.size > 0) console.log(formatTimings(times, performance.now() - t0));
405	    await flushObs();
406	  }
407	}
408	
409	/**
410	 * Sets difficulty and tercile on every outcome (src/difficulty falls back per session: graph, then fan-in).
411	 * A failure of the whole stage leaves both null and adds a note; it never fails the review.
412	 */
413	async function withDifficulty(sessions: Session[], outcomes: Outcome[], repo: string, notes: string[]): Promise<Outcome[]> {
414	  try {
415	    const { scores } = await reviewDifficulty(sessions, repo);
416	    const byId = new Map(scores.map((d) => [d.session_id, d]));
417	    return outcomes.map((o) => {
418	      const d = byId.get(o.session_id);
419	      return { ...o, difficulty: d?.difficulty ?? null, tercile: d?.tercile ?? null };
420	    });
421	  } catch (err) {
422	    notes.push(`difficulty could not be scored, so no session is difficulty-matched: ${err instanceof Error ? err.message : String(err)}`);
423	    return outcomes;
424	  }
425	}
