439	export function verdict(sessions: Session[], outcomes: Outcome[]): Verdict {
440	  const setupOf = new Map(sessions.map((s) => [s.id, s.setup_id]));
441	  const j = suspect(outcomes.map((o): SetupOutcome => ({ ...o, setup_id: setupOf.get(o.session_id) ?? null })));
442	  // erfc can return a hair above 1 at zero deviation (src/review/stats.ts), so p is clamped to the Review type's [0, 1].
443	  const base = { suspect: j.setupId, odds_ratio: j.or, ci95: j.ci95, p_value: j.p === null ? null : Math.min(1, j.p), reason: j.reason };
444	  if (j.label === SUSPECT_LABEL && j.setupId !== null && j.or !== null && j.ci95 !== null && j.p !== null) {
445	    const [lo, hi] = j.ci95;
446	    return {
447	      ...base,
448	      label: "suspect",
449	      note:
450	        `Setup ${j.setupId} is flagged. Comparing sessions of the same difficulty tercile, its bad outcomes ` +
451	        `(reverted, or more than 30% of its lines reworked by a human) have odds ${j.or.toFixed(2)} times the other setups' ` +
452	        `(95% CI ${lo.toFixed(2)} to ${hi.toFixed(2)}, p ${j.p.toFixed(4)}). This is observational evidence, not proof.`,
453	    };
454	  }
455	  if (j.label === NO_SUSPECT_LABEL) {
456	    return {
457	      ...base,
458	      label: "no_suspect",
459	      suspect: null,
460	      note: `No setup is flagged: ${j.reason}. The highest matched odds ratio is shown for context only.`,
461	    };
462	  }
463	  return {
464	    ...base,
465	    label: "insufficient_data",
466	    suspect: null,
467	    odds_ratio: null,
468	    ci95: null,
469	    p_value: null,
470	    note: `No suspect call: ${j.reason}.`,
471	  };
472	}
