7	const TOLERANCE = 0.005;
8	
9	function flatten(v: unknown, path: string, out: Map<string, unknown>): void {
10	  if (Array.isArray(v)) {
11	    if (v.length === 0) out.set(path, v);
12	    v.forEach((x, i) => flatten(x, `${path}[${i}]`, out));
13	  } else if (v !== null && typeof v === "object") {
14	    const keys = Object.keys(v);
15	    if (keys.length === 0) out.set(path, v);
16	    for (const k of keys) flatten((v as Record<string, unknown>)[k], path ? `${path}.${k}` : k, out);
17	  } else {
18	    out.set(path, v);
19	  }
20	}
