22	function same(a: unknown, b: unknown): boolean {
23	  if (typeof a === "number" && typeof b === "number") return Math.abs(a - b) <= TOLERANCE;
24	  if (Array.isArray(a) && Array.isArray(b)) return a.length === 0 && b.length === 0;
25	  if (a !== null && b !== null && typeof a === "object" && typeof b === "object") {
26	    return Object.keys(a).length === 0 && Object.keys(b).length === 0;
27	  }
28	  return a === b;
29	}
