31	export function diffBook(sent: Book, readback: Book): Diff[] {
32	  const s = new Map<string, unknown>();
33	  const g = new Map<string, unknown>();
34	  flatten(sent, "", s);
35	  flatten(readback ?? {}, "", g);
36	  const paths = [...s.keys(), ...[...g.keys()].filter((p) => !s.has(p))];
37	  const diffs: Diff[] = [];
38	  for (const path of paths) {
39	    const a = s.get(path);
40	    const b = g.get(path);
41	    if (!s.has(path) || !g.has(path) || !same(a, b)) diffs.push({ path, sent: a, got: b });
42	  }
43	  return diffs;
44	}
