47	  book: Book,
48	  client: Client,
49	  opts: { retries?: number } = {},
50	): Promise<{ ok: boolean; attempts: number; diffs: Diff[] }> {
51	  const maxAttempts = 1 + Math.max(0, opts.retries ?? 1);
52	  let diffs: Diff[] = [];
53	  let attempts = 0;
54	  while (attempts < maxAttempts) {
55	    attempts++;
56	    try {
57	      await client.call("edit_table_blocks", { book });
58	      const res = (await client.call("inspect_table_blocks", {})) as { book?: Book } | null | undefined;
